"""lid_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 5 extrusion(s) and 3 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python lid_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -0.625    # level along z
z1 = 0.0    # level along z
z2 = 1.25    # level along z
z3 = 1.875    # level along z
z4 = 2.5    # level along z
hole_d = 5.0

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z -0.625 to 0.0 ------------------------------
outline_1 = cf.wire(
    Edge.makeCircle(3.75, P(-47.0, 0.0), DIR),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: z -0.625 to 0.0 ------------------------------
outline_2 = cf.wire(
    Edge.makeCircle(3.75, P(47.0, 0.0), DIR),
)
part = part + prism(outline_2, z0, z1)

# ---- 3. extrusion: z 0.0 to 2.5 ------------------------------
outline_3 = cf.wire(
    cf.segment(P(-43.8, -15.5), P(43.8, -15.5)),
    Edge.makeThreePointArc(P(43.8, -15.5), P(46.0368, -14.7598), P(47.3669, -12.8782)),
    Edge.makeThreePointArc(P(47.3669, -12.8782), P(49.6346, -9.1346), P(53.3732, -6.8753)),
    Edge.makeThreePointArc(P(53.3732, -6.8753), P(55.2598, -5.5368), P(56.0, -3.3)),
    cf.segment(P(56.0, -3.3), P(56.0, 3.3)),
    Edge.makeThreePointArc(P(56.0, 3.3), P(55.2598, 5.5368), P(53.3732, 6.8753)),
    Edge.makeThreePointArc(P(53.3732, 6.8753), P(49.6346, 9.1346), P(47.3669, 12.8782)),
    Edge.makeThreePointArc(P(47.3669, 12.8782), P(46.0368, 14.7598), P(43.8, 15.5)),
    cf.segment(P(43.8, 15.5), P(-43.8, 15.5)),
    Edge.makeThreePointArc(P(-43.8, 15.5), P(-46.0368, 14.7598), P(-47.3669, 12.8782)),
    Edge.makeThreePointArc(P(-47.3669, 12.8782), P(-49.6346, 9.1346), P(-53.3732, 6.8753)),
    Edge.makeThreePointArc(P(-53.3732, 6.8753), P(-55.2598, 5.5368), P(-56.0, 3.3)),
    cf.segment(P(-56.0, 3.3), P(-56.0, -3.3)),
    Edge.makeThreePointArc(P(-56.0, -3.3), P(-55.2598, -5.5368), P(-53.3732, -6.8753)),
    Edge.makeThreePointArc(P(-53.3732, -6.8753), P(-49.6346, -9.1346), P(-47.3669, -12.8782)),
    Edge.makeThreePointArc(P(-47.3669, -12.8782), P(-46.0368, -14.7598), P(-43.8, -15.5)),
)
part = part + prism(outline_3, z1, z4)

# ---- 4. cut: z 1.25 to 2.5 ------------------------------
outline_4 = cf.wire(
    cf.segment(P(-43.8, 14.25), P(43.8, 14.25)),
    Edge.makeThreePointArc(P(43.8, 14.25), P(45.2942, 13.7543), P(46.196, 12.4865)),
    Edge.makeThreePointArc(P(46.196, 12.4865), P(48.7522, 8.2522), P(52.9709, 5.6977)),
    Edge.makeThreePointArc(P(52.9709, 5.6977), P(54.2414, 4.7847), P(54.73, 3.3)),
    cf.segment(P(54.73, 3.3), P(54.73, -3.3)),
    Edge.makeThreePointArc(P(54.73, -3.3), P(54.2414, -4.7847), P(52.9709, -5.6977)),
    Edge.makeThreePointArc(P(52.9709, -5.6977), P(48.7522, -8.2522), P(46.196, -12.4865)),
    Edge.makeThreePointArc(P(46.196, -12.4865), P(45.2942, -13.7543), P(43.8, -14.25)),
    cf.segment(P(43.8, -14.25), P(-43.8, -14.25)),
    Edge.makeThreePointArc(P(-43.8, -14.25), P(-45.2942, -13.7543), P(-46.196, -12.4865)),
    Edge.makeThreePointArc(P(-46.196, -12.4865), P(-48.7522, -8.2522), P(-52.9709, -5.6977)),
    Edge.makeThreePointArc(P(-52.9709, -5.6977), P(-54.2414, -4.7847), P(-54.73, -3.3)),
    cf.segment(P(-54.73, -3.3), P(-54.73, 3.3)),
    Edge.makeThreePointArc(P(-54.73, 3.3), P(-54.2414, 4.7847), P(-52.9709, 5.6977)),
    Edge.makeThreePointArc(P(-52.9709, 5.6977), P(-48.7522, 8.2522), P(-46.196, 12.4865)),
    Edge.makeThreePointArc(P(-46.196, 12.4865), P(-45.2942, 13.7543), P(-43.8, 14.25)),
)
part = part - prism(outline_4, z2, z4)

# ---- 5. extrusion: z 1.25 to 1.875 ------------------------------
outline_5 = cf.wire(
    Edge.makeCircle(3.75, P(-47.0, 0.0), DIR),
)
part = part + prism(outline_5, z2, z3)

# ---- 6. extrusion: z 1.25 to 1.875 ------------------------------
outline_6 = cf.wire(
    Edge.makeCircle(3.75, P(47.0, 0.0), DIR),
)
part = part + prism(outline_6, z2, z3)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (-47.0, 0.0, hole_d, z0, z3),
    (47.0, 0.0, hole_d, z0, z3),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "lid_exact.step")
